import numpy as np
from scipy.optimize import minimize, least_squares
exec(open('fit.py').read().split("# ---------- Model")[0])  # data + colour code

def basis(c, m, y):
    cols, names = [], []
    for i in range(4):
        for j in range(4):
            for k in range(4):
                if i+j+k <= 3:
                    cols.append(c**i * m**j * y**k)
                    names.append((i,j,k))
    return np.stack(cols, axis=-1), names

B, names = basis(C, M, Y)
nb = B.shape[1]
p = np.load('pbest_cbrt.npy')

def model(p):
    return np.stack([(B@p[:nb])**3, (B@p[nb:2*nb])**3, (B@p[2*nb:])**3], axis=-1)

def dE(p):
    return de2000(lab_meas, xyz_to_lab(np.maximum(model(p), 1e-6)))

d = dE(p); print("start: mean=%.4f max=%.4f" % (d.mean(), d.max()))

# aggressive minimax polish: increasing softmax sharpness
best = (d.max(), d.mean(), p.copy())
for k in [8, 16, 32]:
    def obj(q):
        d = dE(q)
        return d.mean() + np.log(np.mean(np.exp(k*(d - d.max())))) / k + d.max()
    r = minimize(obj, best[2], method='Powell', options={'maxiter':300000, 'maxfev':300000, 'xtol':1e-10, 'ftol':1e-12})
    d = dE(r.x)
    print("k=%d: mean=%.4f max=%.4f" % (k, d.mean(), d.max()))
    if (d.max(), d.mean()) < (best[0], best[1]):
        best = (d.max(), d.mean(), r.x)

p = best[2]
d = dE(p); print("polished: mean=%.4f max=%.4f" % (d.mean(), d.max()))
np.save('pfinal.npy', p)

# ---- emit expression strings, exponents written per-variable (max 3) ----
def term_str(coef, i, j, k, sig=9):
    s = "%.*g" % (sig, coef)
    parts = [s]
    for var, e in (('c',i),('m',j),('y',k)):
        if e == 1: parts.append(var)
        elif e >= 2: parts.append("%s**%d" % (var, e))
    return "*".join(parts)

def poly_str(coefs):
    terms = []
    for coef, (i,j,k) in zip(coefs, names):
        t = term_str(coef, i, j, k)
        terms.append(t)
    out = terms[0]
    for t in terms[1:]:
        out += (" + " + t) if not t.startswith('-') else (" - " + t[1:])
    return out

# scale: c,m,y in the emitted equation are 0-100, our fit used 0-1 -> fold 1/100^deg into coefs
def scaled(coefs):
    out = []
    for coef, (i,j,k) in zip(coefs, names):
        out.append(coef / (100.0**(i+j+k)))
    return out

exprs = {}
for ch, sl in zip("XYZ", [slice(0,nb), slice(nb,2*nb), slice(2*nb,3*nb)]):
    exprs[ch] = "(" + poly_str(scaled(p[sl])) + ")**3"

for ch in "XYZ":
    print(ch, "=", exprs[ch])

# ---- verify by parsing the printed strings exactly ----
import re
env = {"c": rows[:,0], "m": rows[:,1], "y": rows[:,2]}
pred = np.stack([eval(exprs[ch], {"__builtins__": {}}, env) for ch in "XYZ"], axis=-1)
d = de2000(lab_meas, xyz_to_lab(np.maximum(pred,1e-6)))
print("VERIFY from strings: mean dE00=%.4f max=%.4f" % (d.mean(), d.max()))
with open('final_eqs.txt','w') as f:
    for ch in "XYZ":
        f.write("%s = %s\n" % (ch, exprs[ch]))

