import numpy as np
from scipy.optimize import minimize
exec(open('fit.py').read().split("# ---------- Model")[0])

def basis(c, m, y):
    cols, names = [], []
    for i in range(4):
        for j in range(4):
            for k in range(4):
                if i+j+k <= 3:
                    cols.append(c**i * m**j * y**k)
                    names.append((i,j,k))
    return np.stack(cols, axis=-1), names

B, names = basis(C, M, Y)
nb = B.shape[1]

def model(p):
    return np.stack([(B@p[:nb])**3, (B@p[nb:2*nb])**3, (B@p[2*nb:])**3], axis=-1)
def dE(p):
    return de2000(lab_meas, xyz_to_lab(np.maximum(model(p), 1e-6)))

starts = [np.load('pfinal.npy'), np.load('pbest_cbrt.npy')]
cands = []
for s in starts:
    d = dE(s); cands.append((d.mean(), d.max(), s))

# objective: mean + lam*softmax, sweep lam, keep Pareto set
for s in starts:
    for lam in [0.15, 0.3, 0.6]:
        k = 24.0
        def obj(q):
            d = dE(q)
            mx = d.max()
            sm = mx + np.log(np.mean(np.exp(k*(d-mx))))/k
            return d.mean() + lam*sm
        r = minimize(obj, s, method='Powell', options={'maxiter':200000,'maxfev':200000,'xtol':1e-10,'ftol':1e-12})
        d = dE(r.x)
        print("lam=%.2f: mean=%.4f max=%.4f" % (lam, d.mean(), d.max()))
        cands.append((d.mean(), d.max(), r.x))

# pick candidate minimizing mean+max
cands.sort(key=lambda t: t[0]+t[1])
for mn, mx, _ in cands:
    print("cand mean=%.4f max=%.4f sum=%.4f" % (mn, mx, mn+mx))
np.save('pfinal2.npy', cands[0][2])
print("chosen: mean=%.4f max=%.4f" % (cands[0][0], cands[0][1]))

